import React, { useState, useEffect } from "react";
import { db } from "../../firebaseConfig";
import { collection, query, where, getDocs } from "firebase/firestore";
import { useNavigate } from "react-router-dom";
import "./ExamPage.css";

const ExamPage = ({ studentClass }) => {
  const [examTitles, setExamTitles] = useState([]);
  const [selectedExamTitle, setSelectedExamTitle] = useState("");
  const [loading, setLoading] = useState(false);
  const navigate = useNavigate();

  useEffect(() => {
    const fetchExamTitles = async () => {
      setLoading(true);
      try {
        const q = query(
          collection(db, "exams"),
          where("classLevel", "==", studentClass)
        );
        const querySnapshot = await getDocs(q);
        const uniqueExamTitles = Array.from(
          new Set(querySnapshot.docs.map((doc) => doc.data().examTitle))
        );
        setExamTitles(uniqueExamTitles);
      } catch (error) {
        console.error("Error fetching exam titles:", error);
      } finally {
        setLoading(false);
      }
    };

    fetchExamTitles();
  }, [studentClass]);

  const handleExamTitleSelection = (e) => {
    setSelectedExamTitle(e.target.value);
  };

  const startExam = () => {
    if (selectedExamTitle) {
      navigate(`/exam/${selectedExamTitle}`);
    } else {
      alert("Please select an exam title.");
    }
  };

  return (
    <div className="exam-page">
      <h2>Select an Exam Title</h2>
      {loading ? (
        <p>Loading exam titles...</p>
      ) : (
        <>
          <select
            className="exam-title-dropdown"
            value={selectedExamTitle}
            onChange={handleExamTitleSelection}
          >
            <option value="">Select an exam title</option>
            {examTitles.map((examTitle, index) => (
              <option key={index} value={examTitle}>
                {examTitle}
              </option>
            ))}
          </select>
          <button
            onClick={startExam}
            className="start-exam-btn"
            disabled={!selectedExamTitle}
          >
            Start Exam
          </button>
        </>
      )}
    </div>
  );
};

export default ExamPage;
